import 'package:flutter/material.dart';
import '../data/app_database.dart';
class PurchasesPage extends StatefulWidget{const PurchasesPage({super.key});@override State<PurchasesPage> createState()=>_P();}
class _P extends State<PurchasesPage>{List<Map<String,Object?>> rows=[];bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{rows=await AppDatabase.instance.listPurchases();if(mounted)setState(()=>loading=false);}Future<void> add()async{final note=TextEditingController(),total=TextEditingController(),paid=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('New Purchase'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:note,decoration:const InputDecoration(labelText:'Supplier / note')),TextField(controller:total,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Total')),TextField(controller:paid,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Paid'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok!=true)return;await AppDatabase.instance.saveSimplePurchase(note:note.text.trim(),total:double.tryParse(total.text)??0,paid:double.tryParse(paid.text)??0);await load();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Purchases')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Purchase')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?const Center(child:Text('No purchases yet.')):ListView.separated(itemCount:rows.length,separatorBuilder:(_,__)=>const Divider(),itemBuilder:(_,i){final r=rows[i];return ListTile(title:Text('Purchase '+r['id'].toString()),subtitle:Text('Total: '+r['total'].toString()+' • Paid: '+r['paid'].toString()),trailing:Text(r['created_at'].toString()));}));}
